local phoneComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PhoneComponent)
local UIFeelingFavorabilityRoleNode = "Game.UI.Phone.Likability.UIFeelingFavorability.UIFeelingFavorabilityRoleNode"

---@class UIFeelingFavorabilityDialog
local UIFeelingFavorabilityDialog = Class("UIFeelingFavorabilityDialog")

function UIFeelingFavorabilityDialog:__init() 
    self._allCats = {}
    self._curSelectId = nil
end

function UIFeelingFavorabilityDialog:__delete()
    self._allCats = nil
    self._curSelectId = nil
end

function UIFeelingFavorabilityDialog:Awake()
    self.EventRefeshUIFeelingFavorabilityRewardDialog = Events.AddListener(Constants.EventNames.RefeshUIFeelingFavorabilityRewardDialog, Bind(self, self.OnReshSelf))

    self._allCats = PhoneUtils.GetAllCatIdArray()
    table.sort(self._allCats, function(a, b)
        return (not PhoneUtils.IsUnlockCatById(b) and PhoneUtils.IsUnlockCatById(a))
    end)
    self.LoopViewCard:InitGridView(#self._allCats, Bind(self, self.OnGetRoleCellByIndex))
end

function UIFeelingFavorabilityDialog:OnGetRoleCellByIndex(listView, index)
    if index < 0 then
        return nil
    end

    local id = self._allCats[index + 1]
    local cell = listView:NewListViewItem("itemcel")
    local scr = CfUtils.GetLuaScr(cell, UIFeelingFavorabilityRoleNode)
    if scr then
        scr:Refresh(id, function()
            self:OnSelectRole(index)
        end, index)
    end

    if self._curSelectId and checkNumber(self._curSelectId) == checkNumber(id) then
        if scr then
            scr:RefreshSelect()
        end
    end
    return cell
end

function UIFeelingFavorabilityDialog:OnSelectRole(index)
    --如果没有选中的
    if not self._curSelectId then
        local go = self.LoopViewCard:GetShownItemByItemIndex(index)
        if go then 
            local scr = CfUtils.GetLuaScr(go, UIFeelingFavorabilityRoleNode)
            if scr then
                scr:RefreshSelect()
            end
        end
        self._curSelectId = self._allCats[index + 1]
    else   
        local key = checkNumber(table.keyof(self._allCats, checkString(self._curSelectId)))
        local go = self.LoopViewCard:GetShownItemByItemIndex(key - 1)
        if go then
            local scr = CfUtils.GetLuaScr(go, UIFeelingFavorabilityRoleNode)
            if scr then
                scr:RefreshUnSelect()
            end
        end
        self._curSelectId = nil
    end
end

function UIFeelingFavorabilityDialog:OnReshSelf()
    GameUtils.ReloadData(self.LoopViewCard, #self._allCats)
end

function UIFeelingFavorabilityDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        CfUtils.SetTopCommonActive(true, false)
    end))
    return coWait
end

function UIFeelingFavorabilityDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if not isNull(self) then
            Events.RemoveListener(Constants.EventNames.RefeshUIFeelingFavorabilityRewardDialog, self.EventRefeshUIFeelingFavorabilityRewardDialog)
        end
        GameUtils.SetRedPointNum(Constants.RedPointConst.PhoneReward, PhoneUtils.IsHasNotDrawReward() and 1 or 0)
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIFeelingFavorabilityDialog
